"""Random arrays and window sizes, weighted towards the shapes that stress
the deque differently: monotonic runs (deque stays small or stays full) and
arrays full of ties."""


def generate(rng, count):
    builders = (_random, _increasing, _decreasing, _many_ties)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, window, description=""):
    return {"name": name,
            "stdin": "%d %d\n%s\n" % (len(values), window,
                                        " ".join(map(str, values))),
            "description": description}


def _random(rng, index):
    n = rng.randint(1, 25)
    window = rng.randint(1, n)
    values = [rng.randint(-50, 50) for _ in range(n)]
    return _case("a random array, window %d of %d #%d" % (window, n, index),
                 values, window)


def _increasing(rng, index):
    n = rng.randint(3, 20)
    window = rng.randint(1, n)
    values = sorted(rng.sample(range(-50, 50), n))
    return _case("a strictly increasing array #%d" % index, values, window,
                 "Every index stays in the deque until it ages out -- the "
                 "deque grows to the full window size.")


def _decreasing(rng, index):
    n = rng.randint(3, 20)
    window = rng.randint(1, n)
    values = sorted(rng.sample(range(-50, 50), n), reverse=True)
    return _case("a strictly decreasing array #%d" % index, values, window,
                 "Every new value evicts everything before it -- the deque "
                 "never holds more than one index.")


def _many_ties(rng, index):
    n = rng.randint(5, 20)
    window = rng.randint(2, n)
    pool = [rng.randint(-5, 5) for _ in range(3)]
    values = [rng.choice(pool) for _ in range(n)]
    return _case("many repeated values #%d" % index, values, window,
                 "Ties must be evicted from the back too, or stale equal "
                 "values pile up unread.")
